102	     * Return whether input matches regex of exact mobile.
103	     *
104	     * @param input       The input.
105	     * @param newSegments The new segments of mobile number.
106	     * @return {@code true}: yes<br>{@code false}: no
107	     */
108	    public static boolean isMobileExact(final CharSequence input, List<String> newSegments) {
109	        boolean match = isMatch(RegexConstants.REGEX_MOBILE_EXACT, input);
110	        if (match) return true;
111	        if (newSegments == null) return false;
112	        if (input == null || input.length() != 11) return false;
113	        String content = input.toString();
114	        for (char c : content.toCharArray()) {
115	            if (!Character.isDigit(c)) {
116	                return false;
117	            }
118	        }
119	        for (String newSegment : newSegments) {
120	            if (content.startsWith(newSegment)) {
121	                return true;
122	            }
123	        }
124	        return false;
125	    }
