157	    /**
158	     * Return whether input matches regex of exact id card number which length is 18.
159	     *
160	     * @param input The input.
161	     * @return {@code true}: yes<br>{@code false}: no
162	     */
163	    public static boolean isIDCard18Exact(final CharSequence input) {
164	        if (isIDCard18(input)) {
165	            int[] factor = new int[]{7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2};
166	            char[] suffix = new char[]{'1', '0', 'X', '9', '8', '7', '6', '5', '4', '3', '2'};
167	            if (CITY_MAP.isEmpty()) {
168	                CITY_MAP.put("11", "北京");
169	                CITY_MAP.put("12", "天津");
170	                CITY_MAP.put("13", "河北");
171	                CITY_MAP.put("14", "山西");
172	                CITY_MAP.put("15", "内蒙古");
173	
174	                CITY_MAP.put("21", "辽宁");
175	                CITY_MAP.put("22", "吉林");
176	                CITY_MAP.put("23", "黑龙江");
177	
178	                CITY_MAP.put("31", "上海");
179	                CITY_MAP.put("32", "江苏");
180	                CITY_MAP.put("33", "浙江");
181	                CITY_MAP.put("34", "安徽");
182	                CITY_MAP.put("35", "福建");
183	                CITY_MAP.put("36", "江西");
184	                CITY_MAP.put("37", "山东");
185	
186	                CITY_MAP.put("41", "河南");
187	                CITY_MAP.put("42", "湖北");
188	                CITY_MAP.put("43", "湖南");
189	                CITY_MAP.put("44", "广东");
190	                CITY_MAP.put("45", "广西");
191	                CITY_MAP.put("46", "海南");
192	
193	                CITY_MAP.put("50", "重庆");
194	                CITY_MAP.put("51", "四川");
195	                CITY_MAP.put("52", "贵州");
196	                CITY_MAP.put("53", "云南");
197	                CITY_MAP.put("54", "西藏");
198	
199	                CITY_MAP.put("61", "陕西");
200	                CITY_MAP.put("62", "甘肃");
201	                CITY_MAP.put("63", "青海");
202	                CITY_MAP.put("64", "宁夏");
203	                CITY_MAP.put("65", "新疆");
204	
205	                CITY_MAP.put("71", "台湾老");
206	                CITY_MAP.put("81", "香港");
207	                CITY_MAP.put("82", "澳门");
208	                CITY_MAP.put("83", "台湾新");
209	                CITY_MAP.put("91", "国外");
210	            }
211	            if (CITY_MAP.get(input.subSequence(0, 2).toString()) != null) {
212	                int weightSum = 0;
213	                for (int i = 0; i < 17; ++i) {
214	                    weightSum += (input.charAt(i) - '0') * factor[i];
215	                }
216	                int idCardMod = weightSum % 11;
217	                char idCardLast = input.charAt(17);
218	                return idCardLast == suffix[idCardMod];
219	            }
220	        }
221	        return false;
222	    }
