291	     * @param input The input.
292	     * @return {@code true}: yes<br>{@code false}: no
293	     */
294	    public static boolean isMatch(final String regex, final CharSequence input) {
295	        return input != null && input.length() > 0 && Pattern.matches(regex, input);
296	    }
