298	    /**
299	     * Return the list of input matches the regex.
300	     *
301	     * @param regex The regex.
302	     * @param input The input.
303	     * @return the list of input matches the regex
304	     */
305	    public static List<String> getMatches(final String regex, final CharSequence input) {
306	        if (input == null) return Collections.emptyList();
307	        List<String> matches = new ArrayList<>();
308	        Pattern pattern = Pattern.compile(regex);
309	        Matcher matcher = pattern.matcher(input);
310	        while (matcher.find()) {
311	            matches.add(matcher.group());
312	        }
313	        return matches;
314	    }
