333	     * @param regex       The regex.
334	     * @param replacement The replacement string.
335	     * @return the string constructed by replacing the first matching
336	     * subsequence by the replacement string, substituting captured
337	     * subsequences as needed
338	     */
339	    public static String getReplaceFirst(final String input,
340	                                         final String regex,
341	                                         final String replacement) {
342	        if (input == null) return "";
343	        return Pattern.compile(regex).matcher(input).replaceFirst(replacement);
344	    }
