347	     * Replace every subsequence of the input sequence that matches the
348	     * pattern with the given replacement string.
349	     *
350	     * @param input       The input.
351	     * @param regex       The regex.
352	     * @param replacement The replacement string.
353	     * @return the string constructed by replacing each matching subsequence
354	     * by the replacement string, substituting captured subsequences
355	     * as needed
356	     */
357	    public static String getReplaceAll(final String input,
358	                                       final String regex,
359	                                       final String replacement) {
360	        if (input == null) return "";
361	        return Pattern.compile(regex).matcher(input).replaceAll(replacement);
362	    }
