21	public class MapUtils {
22	
23	    private MapUtils() {
24	        throw new UnsupportedOperationException("u can't instantiate me...");
25	    }
26	
27	    /**
28	     * Returns a new read-only map with the specified contents, given as a list of pairs
29	     * where the first value is the key and the second is the value.
30	     *
31	     * @param pairs a list of pairs
32	     * @return a new read-only map with the specified contents
33	     */
34	    @SafeVarargs
35	    public static <K, V> Map<K, V> newUnmodifiableMap(final Pair<K, V>... pairs) {
36	        return Collections.unmodifiableMap(newHashMap(pairs));
37	    }
38	
39	    @SafeVarargs
40	    public static <K, V> HashMap<K, V> newHashMap(final Pair<K, V>... pairs) {
41	        HashMap<K, V> map = new HashMap<>();
42	        if (pairs == null || pairs.length == 0) {
43	            return map;
44	        }
45	        for (Pair<K, V> pair : pairs) {
46	            if (pair == null) continue;
47	            map.put(pair.first, pair.second);
48	        }
49	        return map;
50	    }
51	
52	    @SafeVarargs
53	    public static <K, V> LinkedHashMap<K, V> newLinkedHashMap(final Pair<K, V>... pairs) {
54	        LinkedHashMap<K, V> map = new LinkedHashMap<>();
55	        if (pairs == null || pairs.length == 0) {
56	            return map;
57	        }
58	        for (Pair<K, V> pair : pairs) {
59	            if (pair == null) continue;
60	            map.put(pair.first, pair.second);
61	        }
62	        return map;
63	    }
64	
65	    @SafeVarargs
66	    public static <K, V> TreeMap<K, V> newTreeMap(final Comparator<K> comparator,
67	                                                  final Pair<K, V>... pairs) {
68	        if (comparator == null) {
69	            throw new IllegalArgumentException("comparator must not be null");
70	        }
71	        TreeMap<K, V> map = new TreeMap<>(comparator);
72	        if (pairs == null || pairs.length == 0) {
73	            return map;
74	        }
75	        for (Pair<K, V> pair : pairs) {
76	            if (pair == null) continue;
77	            map.put(pair.first, pair.second);
78	        }
79	        return map;
80	    }
81	
82	    @SafeVarargs
83	    public static <K, V> Hashtable<K, V> newHashTable(final Pair<K, V>... pairs) {
84	        Hashtable<K, V> map = new Hashtable<>();
85	        if (pairs == null || pairs.length == 0) {
86	            return map;
87	        }
88	        for (Pair<K, V> pair : pairs) {
89	            if (pair == null) continue;
90	            map.put(pair.first, pair.second);
91	        }
92	        return map;
93	    }
94	
95	    /**
96	     * Null-safe check if the specified map is empty.
97	     * <p>
98	     * Null returns true.
99	     *
100	     * @param map the map to check, may be null
101	     * @return true if empty or null
102	     */
103	    public static boolean isEmpty(Map map) {
104	        return map == null || map.size() == 0;
105	    }
106	
107	    /**
108	     * Null-safe check if the specified map is not empty.
109	     * <p>
110	     * Null returns false.
111	     *
112	     * @param map the map to check, may be null
113	     * @return true if non-null and non-empty
114	     */
115	    public static boolean isNotEmpty(Map map) {
116	        return !isEmpty(map);
117	    }
118	
119	    /**
120	     * Gets the size of the map specified.
121	     *
122	     * @param map The map.
123	     * @return the size of the map specified
124	     */
125	    public static int size(Map map) {
126	        if (map == null) return 0;
127	        return map.size();
128	    }
129	
130	    /**
131	     * Executes the given closure on each element in the collection.
132	     * <p>
133	     * If the input collection or closure is null, there is no change made.
134	     *
135	     * @param map     the map to get the input from, may be null
136	     * @param closure the closure to perform, may be null
137	     */
138	    public static <K, V> void forAllDo(Map<K, V> map, Closure<K, V> closure) {
139	        if (map == null || closure == null) return;
140	        for (Map.Entry<K, V> kvEntry : map.entrySet()) {
141	            closure.execute(kvEntry.getKey(), kvEntry.getValue());
142	        }
143	    }
144	
145	    /**
146	     * Transform the map by applying a Transformer to each element.
147	     * <p>
148	     * If the input map or transformer is null, there is no change made.
149	     *
150	     * @param map         the map to get the input from, may be null
151	     * @param transformer the transformer to perform, may be null
152	     */
153	    public static <K1, V1, K2, V2> Map<K2, V2> transform(Map<K1, V1> map, final Transformer<K1, V1, K2, V2> transformer) {
154	        if (map == null || transformer == null) return null;
155	        try {
156	            final Map<K2, V2> transMap = map.getClass().newInstance();
157	            forAllDo(map, new Closure<K1, V1>() {
158	                @Override
159	                public void execute(K1 key, V1 value) {
160	                    Pair<K2, V2> pair = transformer.transform(key, value);
161	                    transMap.put(pair.first, pair.second);
162	                }
163	            });
164	            return transMap;
165	        } catch (IllegalAccessException e) {
166	            e.printStackTrace();
167	        } catch (InstantiationException e) {
168	            e.printStackTrace();
169	        }
170	        return null;
171	    }
172	
173	    /**
174	     * Return the string of map.
175	     *
176	     * @param map The map.
177	     * @return the string of map
178	     */
179	    public static String toString(Map map) {
180	        if (map == null) return "null";
181	        return map.toString();
182	    }
183	
184	    public interface Closure<K, V> {
185	        void execute(K key, V value);
186	    }
187	
188	    public interface Transformer<K1, V1, K2, V2> {
189	        Pair<K2, V2> transform(K1 k1, V1 v1);
190	    }
191	}
