13	/**
14	 * <pre>
15	 *     author: Blankj
16	 *     blog  : http://blankj.com
17	 *     time  : 2020/09/01
18	 *     desc  : utils about debouncing
19	 * </pre>
20	 */
21	public class DebouncingUtils {
22	
23	    private static final int               CACHE_SIZE               = 64;
24	    private static final Map<String, Long> KEY_MILLIS_MAP           = new ConcurrentHashMap<>(CACHE_SIZE);
25	    private static final long              DEBOUNCING_DEFAULT_VALUE = 1000;
26	
27	    private DebouncingUtils() {
28	        throw new UnsupportedOperationException("u can't instantiate me...");
29	    }
30	
31	    /**
32	     * Return whether the view is not in a jitter state.
33	     *
34	     * @param view The view.
35	     * @return {@code true}: yes<br>{@code false}: no
36	     */
37	    public static boolean isValid(@NonNull final View view) {
38	        return isValid(view, DEBOUNCING_DEFAULT_VALUE);
39	    }
40	
41	    /**
42	     * Return whether the view is not in a jitter state.
43	     *
44	     * @param view     The view.
45	     * @param duration The duration.
46	     * @return {@code true}: yes<br>{@code false}: no
47	     */
48	    public static boolean isValid(@NonNull final View view, final long duration) {
49	        return isValid(String.valueOf(view.hashCode()), duration);
50	    }
51	
52	    /**
53	     * Return whether the key is not in a jitter state.
54	     *
55	     * @param key      The key.
56	     * @param duration The duration.
57	     * @return {@code true}: yes<br>{@code false}: no
58	     */
59	    public static boolean isValid(@NonNull String key, final long duration) {
60	        if (TextUtils.isEmpty(key)) {
61	            throw new IllegalArgumentException("The key is null.");
62	        }
63	        if (duration < 0) {
64	            throw new IllegalArgumentException("The duration is less than 0.");
65	        }
66	        long curTime = SystemClock.elapsedRealtime();
67	        clearIfNecessary(curTime);
68	        Long validTime = KEY_MILLIS_MAP.get(key);
69	        if (validTime == null || curTime >= validTime) {
70	            KEY_MILLIS_MAP.put(key, curTime + duration);
71	            return true;
72	        }
73	        return false;
74	    }
75	
76	    private static void clearIfNecessary(long curTime) {
77	        if (KEY_MILLIS_MAP.size() < CACHE_SIZE) return;
78	        for (Iterator<Map.Entry<String, Long>> it = KEY_MILLIS_MAP.entrySet().iterator(); it.hasNext(); ) {
79	            Map.Entry<String, Long> entry = it.next();
80	            Long validTime = entry.getValue();
81	            if (curTime >= validTime) {
82	                it.remove();
83	            }
84	        }
85	    }
86	}
