829	    /**
830	     * Create the span string.
831	     *
832	     * @return the span string
833	     */
834	    public SpannableStringBuilder create() {
835	        applyLast();
836	        if (mTextView != null) {
837	            mTextView.setText(mBuilder);
838	        }
839	        isCreated = true;
840	        return mBuilder;
841	    }
842	
843	    private void applyLast() {
844	        if (isCreated) {
845	            return;
846	        }
847	        if (mType == mTypeCharSequence) {
848	            updateCharCharSequence();
849	        } else if (mType == mTypeImage) {
850	            updateImage();
851	        } else if (mType == mTypeSpace) {
852	            updateSpace();
853	        }
854	        setDefault();
855	    }
856	
857	    private void updateCharCharSequence() {
858	        if (mText.length() == 0) return;
859	        int start = mBuilder.length();
860	        if (start == 0 && lineHeight != -1) {// bug of LineHeightSpan when first line
861	            mBuilder.append(Character.toString((char) 2))
862	                    .append("\n")
863	                    .setSpan(new AbsoluteSizeSpan(0), 0, 2, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
864	            start = 2;
865	        }
866	        mBuilder.append(mText);
867	        int end = mBuilder.length();
868	        if (verticalAlign != -1) {
869	            mBuilder.setSpan(new VerticalAlignSpan(verticalAlign), start, end, flag);
870	        }
871	        if (foregroundColor != COLOR_DEFAULT) {
872	            mBuilder.setSpan(new ForegroundColorSpan(foregroundColor), start, end, flag);
873	        }
874	        if (backgroundColor != COLOR_DEFAULT) {
875	            mBuilder.setSpan(new BackgroundColorSpan(backgroundColor), start, end, flag);
876	        }
877	        if (first != -1) {
878	            mBuilder.setSpan(new LeadingMarginSpan.Standard(first, rest), start, end, flag);
879	        }
880	        if (quoteColor != COLOR_DEFAULT) {
881	            mBuilder.setSpan(
882	                    new CustomQuoteSpan(quoteColor, stripeWidth, quoteGapWidth),
883	                    start,
884	                    end,
885	                    flag
886	            );
887	        }
888	        if (bulletColor != COLOR_DEFAULT) {
889	            mBuilder.setSpan(
890	                    new CustomBulletSpan(bulletColor, bulletRadius, bulletGapWidth),
891	                    start,
892	                    end,
893	                    flag
894	            );
