     * @return the single {@link SpanUtils} instance
     */
    public SpanUtils setFontSize(@IntRange(from = 0) final int size, final boolean isSp) {
        if (isSp) {
            final float fontScale = Resources.getSystem().getDisplayMetrics().scaledDensity;
